python3 << 'EOF'
import pdfplumber

pdf_data = []

# Extract all tables from all pages
with pdfplumber.open('/root/employees_backup.pdf') as pdf:
    for page_num, page in enumerate(pdf.pages):
        tables = page.extract_tables()
        if tables:
            for table in tables:
                for row_idx, row in enumerate(table):
                    # Skip header row (first row contains column names)
                    if row_idx == 0 or not row[0]:
                        continue
                    # Skip empty rows
                    if all(cell is None or str(cell).strip() == '' for cell in row):
                        continue
                    pdf_data.append(row)

print(f"Total records extracted from PDF: {len(pdf_data)}")
print(f"\nFirst 3 records:")
for record in pdf_data[:3]:
    print(record)
print(f"\nLast 3 records:")
for record in pdf_data[-3:]:
    print(record)

